function openProduct(){
  const w=win('Registrar producto',true);
  w.insertAdjacentHTML('beforeend',`<div class="module-heading"><strong>${company()}</strong><strong>Producto con código de barras</strong><span>Registra la publicación y su edición en un solo paso</span></div><form class="form-area"><div class="barcode-card"><label>Código de barras</label><input name="barcode" class="barcode-main" inputmode="numeric" autocomplete="off" autofocus placeholder="Escanea o escribe el código"><small>El lector funciona como teclado: escanea y continúa con los datos del producto.</small></div><div class="form-grid"><label>Clave del producto</label><input name="code" required><label>Nombre</label><input name="title" required><label>Número de edición</label><input name="edition_number" required><label>Descripción de edición</label><input name="edition_name"><label>Precio de venta</label><input name="price" type="number" min="0" step="0.01" required><label>Existencia inicial</label><input name="initial_stock" type="number" min="0" value="0"><label>I.V.A. (%)</label><input name="tax" type="number" min="0" max="100" value="0"><label>Fecha de entrada</label><input name="arrival_date" type="date" value="${new Date().toISOString().slice(0,10)}"><label>Fecha límite de devolución</label><input name="return_deadline" type="date"></div></form><div class="button-row"><button class="win-button save">Guardar producto</button><button class="win-button close-product">Salir</button></div>`);
  w.querySelector('.close-product').onclick=()=>w.remove();
  w.querySelector('.save').onclick=async()=>{const data=Object.fromEntries(new FormData(w.querySelector('form')));const response=await fetch('/api/products',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),out=await response.json();if(response.ok){toast('Producto registrado y disponible para venta');w.remove();loadDashboard()}else toast(out.error||'No fue posible registrar el producto')};
}

openOperation = async function(kind){
  const titles={COMPRA:'Nueva compra',VENTA:'Nueva venta','DEVOLUCION DE CLIENTE':'Devolución de cliente','DEVOLUCION EXTEMPORANEA':'Devolución extemporánea','DEVOLUCION A PROVEEDOR':'Devolución a proveedor',TRASPASO:'Traspaso de inventario'};
  const isSupplier=['COMPRA','DEVOLUCION A PROVEEDOR'].includes(kind),isTransfer=kind==='TRASPASO',isSale=kind==='VENTA',isReturn=kind.includes('DEVOLUCION');
  const preview=await fetch(`/api/next-folio?kind=${encodeURIComponent(kind)}`).then(r=>r.json());
  const w=win(titles[kind]||kind);
  w.insertAdjacentHTML('beforeend',`<div class="operation-head"><label>Folio</label><input name="folio" value="${preview.folio||'Al guardar'}" readonly><label>Fecha</label><input name="operation_date" type="date" value="${new Date().toISOString().slice(0,10)}">${isTransfer?'':`<label>Clave ${isSupplier?'del proveedor':'del cliente'}</label><input name="party_code" autocomplete="off"><label>Nombre</label><input name="party_name" readonly>`}${isSale?'<label>Tipo de venta</label><select name="sale_type"><option value="CONTADO">Contado</option><option value="CREDITO">Crédito</option></select>':''}${isTransfer?'<label>Origen</label><select name="source_store"><option value="BODEGA">Bodega</option><option value="DEVOLUCIONES">Devoluciones</option></select><label>Destino</label><select name="destination_store"><option value="DEVOLUCIONES">Devoluciones</option><option value="BODEGA">Bodega</option></select>':kind==='DEVOLUCION A PROVEEDOR'?'<label>Almacén</label><select name="source_store"><option value="DEVOLUCIONES">Devoluciones</option><option value="BODEGA">Bodega</option></select>':''}</div><div class="scan-strip"><label>▥ Escanear producto</label><input class="scan-input" inputmode="numeric" autocomplete="off" placeholder="Escanea y presiona Enter"><span>También puedes agregarlo por clave y edición.</span></div><div class="ledger"><table class="data-table entry-table"><thead><tr><th>Producto</th><th>Descripción</th><th>Edición</th><th>Existencia</th><th>Precio</th><th>Cantidad</th><th>Descuento</th><th>Importe</th><th></th></tr></thead><tbody></tbody></table><button class="win-button add-line">＋ Agregar manualmente</button></div><div class="totals"><div><span class="parts">Partidas: 0</span><br><span class="copies">Ejemplares: 0</span></div><div class="total-box"><label>Subtotal</label><input name="subtotal" readonly><label>Descuento</label><input name="discount_total" readonly><label>I.V.A.</label><input name="tax_total" readonly><label>Total</label><input name="total" readonly></div></div><div class="button-row"><button class="win-button save">Guardar (F2)</button><button class="win-button close-op">Salir</button></div>`);
  if(isReturn){const categories=kind==='DEVOLUCION A PROVEEDOR'?['NO VENDIDA','DEVOLUCIÓN DE CLIENTE','DAÑADA','ERROR DE INVENTARIO','OTRA']:['NORMAL','NO VENDIDA','DAÑADA','ERROR DE INVENTARIO','EXTEMPORÁNEA','OTRA'];w.querySelector('.operation-head').insertAdjacentHTML('afterend',`<div class="return-details"><label>Categoría de devolución</label><select name="return_category">${categories.map(x=>`<option>${x}</option>`).join('')}</select><label>Notas y aclaraciones</label><textarea name="notes" placeholder="Describe diferencias, errores de inventario o aclaraciones"></textarea></div>`)}
  const tbody=w.querySelector('tbody');
  const recalculate=()=>{let subtotal=0,discountTotal=0,taxTotal=0,copies=0;tbody.querySelectorAll('tr').forEach(tr=>{const price=Number(tr.querySelector('.price').value||0),quantity=Number(tr.querySelector('.quantity').value||0),discount=Number(tr.querySelector('.discount').value||0),tax=Number(tr.dataset.tax||0),base=price*quantity,discounted=base*(1-discount/100),taxAmount=discounted*tax/100;subtotal+=base;discountTotal+=base-discounted;taxTotal+=taxAmount;copies+=quantity;tr.querySelector('.amount').textContent=money(discounted+taxAmount)});w.querySelector('.parts').textContent=`Partidas: ${tbody.children.length}`;w.querySelector('.copies').textContent=`Ejemplares: ${copies}`;w.querySelector('[name=subtotal]').value=money(subtotal);w.querySelector('[name=discount_total]').value=money(discountTotal);w.querySelector('[name=tax_total]').value=money(taxTotal);w.querySelector('[name=total]').value=money(subtotal-discountTotal+taxTotal)};
  const fillRow=(tr,p)=>{tr.dataset.editionId=p.id;tr.dataset.tax=p.tax||0;tr.querySelector('.pub').value=p.publication_code;tr.querySelector('.title').textContent=p.title;tr.querySelector('.edition').value=p.number;tr.querySelector('.stock').textContent=`${p.stock} / ${p.stock_returns}`;tr.querySelector('.price').value=p.price;recalculate()};
  const addLine=(product=null)=>{if(product){const existing=[...tbody.querySelectorAll('tr')].find(x=>Number(x.dataset.editionId)===Number(product.id));if(existing){existing.querySelector('.quantity').value=Number(existing.querySelector('.quantity').value)+1;recalculate();return existing}}const tr=document.createElement('tr');tr.innerHTML='<td><input class="pub" placeholder="Clave"></td><td class="title">Pendiente</td><td><input class="edition" placeholder="Edición"></td><td class="stock">—</td><td><input class="price" type="number" min="0" step="0.01"></td><td><input class="quantity" type="number" min="1" value="1"></td><td><input class="discount" type="number" min="0" max="100" value="0"></td><td class="amount">$0.00</td><td><button class="remove-line" title="Quitar">×</button></td>';tbody.appendChild(tr);const lookup=async()=>{const pub=tr.querySelector('.pub').value,edition=tr.querySelector('.edition').value;if(!pub||!edition)return;const response=await fetch(`/api/edition-lookup?publication=${encodeURIComponent(pub)}&edition=${encodeURIComponent(edition)}`),out=await response.json();if(response.ok)fillRow(tr,out);else toast(out.error)};tr.querySelector('.pub').onchange=lookup;tr.querySelector('.edition').onchange=lookup;tr.querySelectorAll('input').forEach(i=>i.oninput=recalculate);tr.querySelector('.remove-line').onclick=()=>{tr.remove();recalculate()};if(product)fillRow(tr,product);return tr};
  const scan=async()=>{const input=w.querySelector('.scan-input'),barcode=input.value.trim();if(!barcode)return;const response=await fetch(`/api/barcode-lookup?barcode=${encodeURIComponent(barcode)}`),out=await response.json();if(response.ok){addLine(out);input.value='';input.focus()}else toast(out.error)};
  w.querySelector('.scan-input').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();scan()}};
  if(!isTransfer){const partyInput=w.querySelector('[name=party_code]');partyInput.onchange=async()=>{const response=await fetch(`/api/party-lookup?kind=${isSupplier?'supplier':'customer'}&code=${encodeURIComponent(partyInput.value.trim())}`),out=await response.json();w.querySelector('[name=party_name]').value=response.ok?out.name:'';if(!response.ok)toast(out.error)}}
  w.querySelector('.add-line').onclick=()=>addLine().querySelector('.pub').focus();w.querySelector('.close-op').onclick=()=>w.remove();
  const save=async()=>{const q=n=>w.querySelector(`[name=${n}]`)?.value||'';const items=[...tbody.querySelectorAll('tr')].map(tr=>({edition_id:tr.dataset.editionId,price:tr.querySelector('.price').value,quantity:tr.querySelector('.quantity').value,discount:tr.querySelector('.discount').value}));const data={kind,operation_date:q('operation_date'),party_code:q('party_code'),sale_type:q('sale_type'),source_store:q('source_store'),destination_store:q('destination_store'),return_category:q('return_category'),notes:q('notes'),items};const response=await fetch('/api/documents',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),out=await response.json();if(response.ok){toast(`${out.folio} guardado. Total ${money(out.total)}`);if(confirm('Documento guardado. ¿Deseas imprimir el ticket?'))window.open(`/print/documents/${out.id}`,'_blank','width=430,height=700');w.remove();loadDashboard()}else toast(out.error||'No fue posible guardar')};
  w.querySelector('.save').onclick=save;w.onkeydown=e=>{if(e.key==='F2'){e.preventDefault();save()}};w.querySelector('.scan-input').focus();
};

const recordKey={customers:'id',suppliers:'id',publications:'id',editions:'id',priorities:'code',groups:'id',routes:'id',employees:'id',account_types:'id',movement_types:'id',packages:'id'};
const safe=value=>String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');

openCatalog = async function(entity,title){
  if(!columns[entity]){toast('Este panel no corresponde a un catálogo editable');return}
  const w=win(title||'Catálogo'),key=recordKey[entity];let selected=null,timer;
  const hasSupplier=['publications','editions'].includes(entity),hasCategory=entity==='customers';
  w.insertAdjacentHTML('beforeend',`<div class="module-heading"><strong>${company()}</strong><strong>${title||'Catálogo'}</strong><span>Selecciona un registro para editarlo o desactivarlo</span></div><div class="searchbar"><label>Buscar <input class="query" placeholder="Clave, nombre o cualquier dato" autofocus></label>${hasSupplier?'<label>Proveedor <select class="supplier-filter"><option value="">Todos</option></select></label>':''}${hasCategory?'<label>Categoría <select class="category-filter"><option value="">Todas</option></select></label>':''}<div class="catalog-actions"><button class="win-button add">＋ Nuevo</button><button class="win-button edit" disabled>Editar</button><button class="win-button disable" disabled>Desactivar</button>${entity==='routes'?'<button class="win-button route-customers" disabled>Tiendas de la ruta</button><button class="win-button print-route" disabled>Imprimir ruta</button>':''}</div></div><div class="table-wrap"><table class="data-table"><thead><tr>${columns[entity].map(x=>`<th>${x[1]}</th>`).join('')}</tr></thead><tbody></tbody></table></div><div class="status-mini"><span class="catalog-count">Registros: 0</span></div>`);
  if(hasSupplier){const data=await fetch('/api/options/suppliers').then(r=>r.json());w.querySelector('.supplier-filter').insertAdjacentHTML('beforeend',data.map(x=>`<option value="${x.value}">${safe(x.label)}</option>`).join(''))}
  if(hasCategory){const data=await fetch('/api/options/groups').then(r=>r.json());w.querySelector('.category-filter').insertAdjacentHTML('beforeend',data.map(x=>`<option value="${x.value}">${safe(x.label)}</option>`).join(''))}
  const choose=(tr,row)=>{w.querySelectorAll('tbody tr').forEach(x=>x.classList.remove('selected-row'));tr.classList.add('selected-row');selected=row;w.querySelectorAll('.edit,.disable,.route-customers,.print-route').forEach(x=>x.disabled=false)};
  const load=async()=>{const q=w.querySelector('.query').value,supplier=w.querySelector('.supplier-filter')?.value||'',category=w.querySelector('.category-filter')?.value||'';const response=await fetch(`/api/${entity}?limit=1000&q=${encodeURIComponent(q)}&supplier=${encodeURIComponent(supplier)}&category=${encodeURIComponent(category)}`),rows=await response.json();if(!response.ok){toast(rows.error);return}selected=null;w.querySelectorAll('.edit,.disable,.route-customers,.print-route').forEach(x=>x.disabled=true);const body=w.querySelector('tbody');body.innerHTML='';rows.forEach(row=>{const tr=document.createElement('tr');tr.innerHTML=columns[entity].map(([field])=>`<td>${format(row[field],field)}</td>`).join('');tr.onclick=()=>choose(tr,row);tr.ondblclick=()=>openForm(entity,row[key]);body.appendChild(tr)});w.querySelector('.catalog-count').textContent=`Registros: ${rows.length}`};
  w.querySelector('.add').onclick=()=>openForm(entity);w.querySelector('.edit').onclick=()=>selected&&openForm(entity,selected[key]);w.querySelector('.disable').onclick=async()=>{if(!selected||!confirm('¿Deseas desactivar este registro? El historial se conservará.'))return;const response=await fetch(`/api/${entity}/${encodeURIComponent(selected[key])}`,{method:'DELETE'}),out=await response.json();toast(response.ok?'Registro desactivado':out.error);if(response.ok)load()};
  if(entity==='routes'){w.querySelector('.route-customers').onclick=()=>selected&&openRouteCustomers(selected.id);w.querySelector('.print-route').onclick=()=>selected&&window.open(`/print/routes/${selected.id}`,'_blank')}
  w.querySelector('.query').oninput=()=>{clearTimeout(timer);timer=setTimeout(load,180)};w.querySelector('.supplier-filter')?.addEventListener('change',load);w.querySelector('.category-filter')?.addEventListener('change',load);load();
};

openForm = async function(entity,key=null){
  if(entity==='routes')return openRouteForm(key);
  const names={customers:'Cliente',suppliers:'Proveedor',publications:'Publicación',editions:'Edición',priorities:'Prioridad',groups:'Categoría de cliente',employees:'Empleado',account_types:'Cuenta',movement_types:'Tipo de movimiento',packages:'Paquete'};
  let data={};if(key!==null){const response=await fetch(`/api/${entity}/${encodeURIComponent(key)}`);data=await response.json();if(!response.ok){toast(data.error);return}}
  let fields=entity==='packages'?[['customer_code','Clave del cliente'],['publication_code','Clave de la publicación'],['quantity','Cantidad'],['distribution_date','Fecha de reparto'],['active','Estado']]:formFields(entity);
  if(!fields.some(x=>x[0]==='active')&&!['priorities','customers','suppliers','publications','editions'].includes(entity))fields.push(['active','Estado']);
  if(['customers','suppliers','publications','editions'].includes(entity))fields.push(['active','Estado']);
  const optionSources={supplier_id:'suppliers',group_id:'groups',route_id:'routes'};const options={};for(const source of new Set(fields.map(x=>optionSources[x[0]]).filter(Boolean)))options[source]=await fetch(`/api/options/${source}`).then(r=>r.json());
  const control=([field,label,wide])=>{const value=data[field]??(field==='active'?1:'');let html;if(field==='active')html=`<select name="${field}"><option value="1" ${String(value)!=='0'?'selected':''}>Activo</option><option value="0" ${String(value)==='0'?'selected':''}>Inactivo</option></select>`;else if(optionSources[field])html=`<select name="${field}"><option value="">Sin asignar</option>${options[optionSources[field]].map(x=>`<option value="${x.value}" ${String(value)===String(x.value)?'selected':''}>${safe(x.label)}</option>`).join('')}</select>`;else{const type=field.includes('date')||field.includes('deadline')?'date':['balance','discount','percentage','quantity','price','stock','tax','term','order','limit','days','accumulated','return_percentage'].some(x=>field.includes(x))?'number':'text';html=`<input name="${field}" type="${type}" value="${safe(value)}" ${field==='code'&&key!==null&&entity==='priorities'?'readonly':''}>`}return `<label>${label}</label><div class="${wide==='wide'?'span3':''}">${html}</div>`};
  const w=win(`${key===null?'Nuevo':'Editar'} ${names[entity]||'registro'}`,true);w.insertAdjacentHTML('beforeend',`<div class="module-heading"><strong>${company()}</strong><span>Los campos principales deben quedar completos</span></div><form class="form-area"><div class="form-grid">${fields.map(control).join('')}</div></form><div class="button-row"><button class="win-button save">Guardar</button><button class="win-button close-form">Cerrar</button></div>`);w.querySelector('.close-form').onclick=()=>w.remove();w.querySelector('.save').onclick=async()=>{const payload=Object.fromEntries(new FormData(w.querySelector('form'))),url=key===null?`/api/${entity}`:`/api/${entity}/${encodeURIComponent(key)}`,method=key===null?'POST':'PUT';const response=await fetch(url,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),out=await response.json();if(response.ok){toast('Registro guardado');openCatalog(entity,names[entity])}else toast(out.error||'No fue posible guardar')};
};

async function openRouteForm(key=null){
  let data={active:1};if(key!==null)data=await fetch(`/api/routes/${key}`).then(r=>r.json());const employees=await fetch('/api/options/employees').then(r=>r.json()),w=win(`${key===null?'Nueva':'Editar'} ruta de reparto`,true);w.insertAdjacentHTML('beforeend',`<div class="module-heading"><strong>${company()}</strong><strong>Ruta de reparto</strong></div><form class="form-area"><div class="form-grid"><label>Nombre de la ruta</label><input name="name" value="${safe(data.name||'')}" autofocus><label>Repartidor</label><select name="employee_id"><option value="">Sin asignar</option>${employees.map(x=>`<option value="${x.value}" ${String(data.employee_id)===String(x.value)?'selected':''}>${safe(x.label)}</option>`).join('')}</select><label>Estado</label><select name="active"><option value="1">Activa</option><option value="0" ${String(data.active)==='0'?'selected':''}>Inactiva</option></select><label>Indicaciones</label><textarea name="notes" class="span3">${safe(data.notes||'')}</textarea></div><p>Después de guardar podrás seleccionar las tiendas que comprende esta ruta.</p></form><div class="button-row"><button class="win-button save">Guardar y asignar tiendas</button><button class="win-button close-route">Cerrar</button></div>`);w.querySelector('.close-route').onclick=()=>w.remove();w.querySelector('.save').onclick=async()=>{const payload=Object.fromEntries(new FormData(w.querySelector('form'))),response=await fetch(key===null?'/api/routes':`/api/routes/${key}`,{method:key===null?'POST':'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),out=await response.json();if(response.ok)openRouteCustomers(key??out.id);else toast(out.error)};
}

async function openRouteCustomers(routeId){
  const [route,customers]=await Promise.all([fetch(`/api/routes/${routeId}`).then(r=>r.json()),fetch(`/api/routes/${routeId}/customers`).then(r=>r.json())]),w=win(`Tiendas de la ruta: ${route.name}`);w.insertAdjacentHTML('beforeend',`<div class="searchbar"><label>Buscar tienda <input class="route-search" placeholder="Clave, nombre, ciudad o categoría"></label><span>Marca todas las tiendas que comprende la ruta.</span></div><div class="form-area"><div class="route-customer-list">${customers.map(c=>`<label data-search="${safe(`${c.code} ${c.name} ${c.city} ${c.classification}`.toLowerCase())}"><input type="checkbox" value="${c.id}" ${c.selected?'checked':''}><b>${safe(c.code)}</b><span>${safe(c.name)}</span><small>${safe(c.city)} · ${safe(c.classification)}</small></label>`).join('')}</div></div><div class="button-row"><button class="win-button save-route-customers">Guardar tiendas</button><button class="win-button print-route">Imprimir ruta</button><button class="win-button close-route-customers">Cerrar</button></div>`);w.querySelector('.route-search').oninput=e=>w.querySelectorAll('.route-customer-list label').forEach(x=>x.hidden=!x.dataset.search.includes(e.target.value.toLowerCase()));w.querySelector('.close-route-customers').onclick=()=>w.remove();w.querySelector('.print-route').onclick=()=>window.open(`/print/routes/${routeId}`,'_blank');w.querySelector('.save-route-customers').onclick=async()=>{const selected=[...w.querySelectorAll('.route-customer-list input:checked')].map(x=>Number(x.value)),response=await fetch(`/api/routes/${routeId}/customers`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({customers:selected})}),out=await response.json();toast(response.ok?`${out.customers} tiendas asignadas`:out.error)};
}

async function openCustomerCategories(){
  const w=win('Clientes por categorías'),categories=await fetch('/api/options/groups').then(r=>r.json());w.insertAdjacentHTML('beforeend',`<div class="module-heading"><strong>${company()}</strong><strong>Clientes por categorías</strong></div><div class="searchbar"><label>Buscar <input class="query"></label><label>Categoría <select class="category"><option value="">Todas</option>${categories.map(x=>`<option value="${x.value}">${safe(x.label)}</option>`).join('')}</select></label></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Clave</th><th>Cliente</th><th>Categoría</th><th>Ruta</th><th>Ciudad</th><th>Teléfono</th><th>Saldo</th></tr></thead><tbody></tbody></table></div><div class="status-mini count"></div>`);const load=async()=>{const rows=await fetch(`/api/customers?limit=1000&q=${encodeURIComponent(w.querySelector('.query').value)}&category=${w.querySelector('.category').value}`).then(r=>r.json());w.querySelector('tbody').innerHTML=rows.map(x=>`<tr><td>${safe(x.code)}</td><td>${safe(x.name)}</td><td>${safe(x.category)}</td><td>${safe(x.route)}</td><td>${safe(x.city)}</td><td>${safe(x.phone)}</td><td>${money(x.balance)}</td></tr>`).join('');w.querySelector('.count').textContent=`Clientes: ${rows.length}`};w.querySelector('.query').oninput=load;w.querySelector('.category').onchange=load;load();
}

async function openReturnsReport(type){
  const supplier=type==='supplier',w=win(supplier?'Devoluciones a proveedor':'Devoluciones de clientes'),providers=supplier?await fetch('/api/options/suppliers').then(r=>r.json()):[];w.insertAdjacentHTML('beforeend',`<div class="module-heading"><strong>${company()}</strong><strong>${supplier?'Ejemplares no vendidos devueltos al proveedor':'Revistas devueltas por clientes'}</strong></div><div class="searchbar report-filter"><label>Desde <input type="date" name="start" value="2010-01-01"></label><label>Hasta <input type="date" name="end" value="${new Date().toISOString().slice(0,10)}"></label><label>Buscar <input name="q" placeholder="Folio, persona, revista o nota"></label>${supplier?`<label>Proveedor <select name="supplier"><option value="">Todos</option>${providers.map(x=>`<option value="${x.value}">${safe(x.label)}</option>`).join('')}</select></label>`:''}<label>Categoría <select name="category"><option value="">Todas</option>${(supplier?['NO VENDIDA','DEVOLUCIÓN DE CLIENTE','DAÑADA','ERROR DE INVENTARIO','OTRA']:['NORMAL','NO VENDIDA','DAÑADA','ERROR DE INVENTARIO','EXTEMPORÁNEA','OTRA']).map(x=>`<option>${x}</option>`).join('')}</select></label><button class="win-button search-returns">Consultar</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Folio</th><th>Fecha</th><th>Clave</th><th>Nombre</th><th>Categoría</th><th>Revista</th><th>Edición</th><th>Cantidad</th><th>Importe</th><th>Notas</th></tr></thead><tbody></tbody></table></div><div class="totals"><span class="return-count"></span><b class="return-total"></b></div><div class="button-row"><button class="win-button print-returns">Imprimir reporte</button><button class="win-button close-returns">Cerrar</button></div>`);let last=[];const load=async()=>{const q=n=>w.querySelector(`[name=${n}]`)?.value||'',response=await fetch(`/api/returns-report?type=${type}&start=${q('start')}&end=${q('end')}&q=${encodeURIComponent(q('q'))}&supplier=${q('supplier')}&category=${encodeURIComponent(q('category'))}`),out=await response.json();last=out.rows||[];w.querySelector('tbody').innerHTML=last.map(x=>`<tr><td>${safe(x.Folio)}</td><td>${safe(x.Fecha)}</td><td>${safe(x.Clave)}</td><td>${safe(x.Nombre)}</td><td>${safe(x.Categoria)}</td><td>${safe(x.Revista)}</td><td>${safe(x.Edicion)}</td><td>${x.Cantidad}</td><td>${money(x.Importe)}</td><td>${safe(x.Notas)}</td></tr>`).join('');w.querySelector('.return-count').textContent=`Registros: ${out.count||0}`;w.querySelector('.return-total').textContent=`Total: ${money(out.total)}`};w.querySelector('.search-returns').onclick=load;w.querySelector('.print-returns').onclick=()=>printTable(supplier?'Devoluciones a proveedor':'Devoluciones de clientes',['Folio','Fecha','Clave','Nombre','Categoria','Revista','Edicion','Cantidad','Importe','Notas'],last);w.querySelector('.close-returns').onclick=()=>w.remove();load();
}

function printTable(title,fields,rows){const popup=window.open('','_blank','width=1000,height=750');popup.document.write(`<!doctype html><html lang="es"><head><meta charset="utf-8"><title>${safe(title)}</title><style>@page{size:letter landscape;margin:10mm}body{font:11px Arial}h1{font-size:18px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #777;padding:4px}th{background:#ddd}@media print{button{display:none}}</style></head><body><h1>${safe(company())} · ${safe(title)}</h1><table><thead><tr>${fields.map(x=>`<th>${safe(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${fields.map(x=>`<td>${safe(row[x])}</td>`).join('')}</tr>`).join('')}</tbody></table><button onclick="print()">Imprimir</button><script>onload=()=>print()<\/script></body></html>`);popup.document.close()}

