function buildMenus(){
  Object.assign(columns,{
    customers:[['code','Clave'],['name','Nombre'],['category','Categoría'],['route','Ruta'],['rfc','R.F.C.'],['phone','Teléfono'],['city','Ciudad'],['balance','Saldo'],['active','Estado']],
    suppliers:[['code','Clave'],['name','Nombre'],['rfc','R.F.C.'],['phone','Teléfono'],['balance','Saldo'],['active','Estado']],
    publications:[['code','Clave revista'],['title','Título'],['supplier','Proveedor'],['barcode','Código de barras'],['tax','I.V.A.'],['active','Estado']],
    editions:[['publication_code','Clave revista'],['title','Publicación'],['number','Edición'],['barcode','Código de barras'],['price','Precio'],['stock','Bodega'],['arrival_date','Fecha entrada']],
    routes:[['id','Ruta'],['name','Nombre'],['employee','Repartidor'],['customers','Tiendas'],['notes','Indicaciones'],['active','Estado']]
  });
  const nav=document.querySelector('#main-menu');
  menuData.forEach(([icon,label,items])=>{
    const root=document.createElement('div'); root.className='menu-root';
    root.innerHTML=`<button class="menu-label"><span class="ico">${icon}</span>${label}</button>`;
    root.appendChild(dropdown(items)); nav.appendChild(root);
    root.firstChild.onclick=e=>{e.stopPropagation();document.querySelectorAll('.menu-root').forEach(x=>x!==root&&x.classList.remove('open'));root.classList.toggle('open')};
  });
  document.onclick=()=>document.querySelectorAll('.menu-root').forEach(x=>x.classList.remove('open'));
}
function dropdown(items){
  const d=document.createElement('div');d.className='dropdown';
  items.forEach(([label,action,arg,children])=>{
    const holder=document.createElement(children?'div':'button');holder.className=children?'submenu-item':'menu-item';
    if(children){holder.innerHTML=`<button class="menu-item has-next">${label}</button>`;holder.appendChild(dropdown(children));}
    else{holder.textContent=label;holder.onclick=e=>{e.stopPropagation();run(action,arg,label);closeMenus()};}
    d.appendChild(holder);
  });return d;
}
function closeMenus(){document.querySelectorAll('.menu-root').forEach(x=>x.classList.remove('open'))}
function run(action,arg,label){
  if(action==='catalog')openCatalog(arg,label); else if(action==='form')openForm(arg);
  else if(action==='operation')openOperation(arg); else if(action==='operations')openCatalog('operations',label);
  else if(action==='package')openPackage(); else if(action==='product')openProduct(); else if(action==='account')openAccountEntry(arg);
  else if(action==='cancellation')openCancellation(arg);
  else if(action==='customer-categories')openCustomerCategories(); else if(action==='returns-report')openReturnsReport(arg);
  else if(action==='backup'||action==='migration-download'||action==='migration-import')openBackup(action);
  else if(action==='report')openReport(arg||label); else if(action==='settings')openSettings(); else if(action==='about')openAbout();
  else if(action==='exit')window.close();
}
function buildToolbar(){const t=document.querySelector('#toolbar');toolbar.forEach(([i,l,fn])=>{const b=document.createElement('button');b.className='tool';b.innerHTML=`<span class="tool-icon">${i}</span>${l}`;b.onclick=fn;t.appendChild(b)})}
function win(title,compact=false){
  document.querySelectorAll('.mdi-window').forEach(x=>x.remove());
  const w=document.createElement('section');w.className='mdi-window'+(compact?' compact':'');
  w.innerHTML=`<div class="mdi-title"><span>▧</span>&nbsp;<b>${title}</b><div class="mdi-controls"><button>_</button><button>□</button><button class="close">×</button></div></div>`;
  w.querySelector('.close').onclick=()=>w.remove();document.querySelector('#windows').appendChild(w);return w;
}
async function openCatalog(entity,title){
  const w=win(title || entity.toUpperCase());
  w.insertAdjacentHTML('beforeend',`<div class="module-nav"><button>Altas</button><button>Consultas</button><button>Modificaciones</button><button class="nav-exit">Salir</button></div><div class="module-heading"><strong>CARLOS ESPINDOLA</strong><strong>CARLOS ESPINDOLA</strong><span>Catálogo de ${title||entity}</span></div><div class="searchbar"><label>Buscar&nbsp; <input class="query" autofocus></label><button class="win-button find">🔎 Buscar</button><button class="win-button add">➕ Alta</button></div><div class="table-wrap"><table class="data-table"><thead><tr>${columns[entity].map(x=>`<th>${x[1]}</th>`).join('')}</tr></thead><tbody></tbody></table></div><div class="status-mini">${today()} &nbsp;&nbsp; Consulta del catálogo</div>`);
  w.querySelector('.nav-exit').onclick=()=>w.remove(); w.querySelector('.add').onclick=()=>entity==='operations'?openOperation('MOVIMIENTO'):openForm(entity);
  const load=async()=>{const rows=await fetch(`/api/${entity}?q=${encodeURIComponent(w.querySelector('.query').value)}`).then(r=>r.json());w.querySelector('tbody').innerHTML=rows.map(row=>`<tr>${columns[entity].map(([key])=>`<td>${format(row[key],key)}</td>`).join('')}</tr>`).join('')};
  w.querySelector('.find').onclick=load;w.querySelector('.query').onkeydown=e=>e.key==='Enter'&&load();load();
}
function formFields(entity){
  if(entity==='customers')return [['code','Clave'],['rfc','R. F. C.'],['name','Nombre','wide'],['legal_name','R. Soc / Dueño','wide'],['address','Dirección','wide'],['postal_code','C.P.'],['city','Ciudad'],['state','Estado'],['phone','Teléfono(s)'],['fax','Fax'],['zone','Zona'],['classification','Clasificación'],['discount','Descuento (%)'],['priority','Prioridad'],['group_id','Grupo'],['route_id','Ruta'],['distribution_order','No. de Reparto'],['return_percentage','Devolución al (%)'],['payment_condition','Condición CONTADO/CREDITO'],['payment_term','Plazo'],['first_payment_day','1er. Día de Pago'],['second_payment_day','2do. Día de Pago'],['buyer','Encargado de Compras'],['payer','Encargado de Pagos'],['representative','Representante'],['credit_limit','Límite Crédito'],['balance','Saldo Inicial'],['email','Correo']];
  if(entity==='suppliers')return [['code','Clave'],['rfc','Reg. Fed. Caus.'],['name','Nombre'],['legal_name','Razón Social'],['address','Dirección'],['city','Ciudad'],['state','Estado'],['postal_code','C.P.'],['phone','Teléfono'],['mobile','Celular'],['email','Correo'],['payment_condition','Condiciones de Pago'],['supplier_return_days','Días Límite Devolución'],['customer_return_days','Días Límite Cliente'],['balance','Saldo']];
  if(entity==='publications')return [['code','Clave revista'],['supplier_id','Clave Proveedor'],['supplier_publication_code','Clave del Proveedor'],['title','Nombre Revista','wide'],['barcode','Código de Barras'],['tax','I.V.A. (%)'],['top25','Más vendidas']];
  if(entity==='editions')return [['publication_code','Clave revista'],['legacy_code','Clave edición'],['number','No. Edición'],['name','Nombre edición','wide'],['barcode','Código de Barras'],['arrival_date','Fecha Entrada'],['supplier_deadline','Vencimiento Proveedor'],['return_deadline','Vencimiento Cliente'],['price','Precio'],['customer_discount','Descuento Cliente'],['stock','Existencia Bodega'],['stock_returns','Existencia Devoluciones']];
  if(entity==='priorities')return [['code','Prioridad'],['percentage','Porcentaje']];
  if(entity==='groups')return [['name','Nombre del grupo'],['accumulated','Acumulado'],['active','Estado (1=Activo)']];
  if(entity==='routes')return [['name','Nombre de ruta'],['active','Estado (1=Activo)']];
  if(entity==='employees')return [['name','Nombre'],['position','Puesto'],['area','Área'],['active','Estado (1=Activo)']];
  if(entity==='account_types')return [['name','Nombre de cuenta'],['kind','Tipo CARGO/ABONO'],['active','Estado (1=Activo)']];
  return [['concept','Concepto'],['kind','Tipo Entrada/Salida'],['active','Estado (1=Activo)']];
}
function openForm(entity){
  const names={customers:'MODULO DE CLIENTES',suppliers:'Modulo de Proveedores',publications:'Modulo de Revistas',editions:'Modulo de Ediciones'};const w=win(names[entity]||'Catálogo',true);const fields=formFields(entity);
  w.insertAdjacentHTML('beforeend',`<div class="module-nav"><button>Altas</button><button>Consultas</button><button>Modificaciones</button><button class="nav-exit">Salir</button></div><div class="module-heading"><strong>CARLOS ESPINDOLA</strong><strong>CARLOS ESPINDOLA</strong><span>Alta de ${entity==='customers'?'cliente':entity==='suppliers'?'proveedor':'revista'}</span></div><div class="tabs"><button class="tab">Datos Generales</button><button class="tab">Condiciones</button></div><form class="form-area"><div class="form-grid">${fields.map(([key,label,wide])=>`<label>${label}</label><input name="${key}" class="${wide==='wide'?'span3':''}">`).join('')}</div></form><div class="button-row"><button class="win-button save">💾 Guardar</button><button class="win-button nav-exit">🚪 Salir</button></div><div class="status-mini">${today()} &nbsp;&nbsp; CLAVE DEL REGISTRO</div>`);
  w.querySelectorAll('.nav-exit').forEach(b=>b.onclick=()=>w.remove());
  w.querySelector('.save').onclick=async()=>{const data=Object.fromEntries(new FormData(w.querySelector('form')));const r=await fetch(`/api/${entity}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const out=await r.json();if(r.ok){toast('Registro guardado correctamente');w.remove();openCatalog(entity,names[entity])}else toast(out.error||'No fue posible guardar')};
}
function openPackage(){const w=win('Modulo de Paquetes',true);w.insertAdjacentHTML('beforeend',`<div class="module-heading"><strong>CARLOS ESPINDOLA</strong><strong>Alta de Paquetes</strong></div><form class="form-area"><div class="form-grid"><label>Clave Cliente</label><input name="customer_code"><label>Clave Revista</label><input name="publication_code"><label>Cantidad</label><input name="quantity" type="number" min="0" value="1"><label>Fecha Reparto</label><input name="distribution_date" type="date" value="${new Date().toISOString().slice(0,10)}"></div><p>El paquete define la cantidad de ejemplares de una revista que se asignará al cliente cuando se genere el reparto.</p></form><div class="button-row"><button class="win-button save">💾 Guardar</button><button class="win-button close-package">🚪 Salir</button></div><div class="status-mini">${today()} &nbsp;&nbsp; Clave del Cliente</div>`);w.querySelector('.close-package').onclick=()=>w.remove();w.querySelector('.save').onclick=async()=>{const data=Object.fromEntries(new FormData(w.querySelector('form')));const r=await fetch('/api/packages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),out=await r.json();if(r.ok){toast('Paquete guardado');w.remove()}else toast(out.error)}}
function openAccountEntry(ledger){const receivable=ledger==='receivable',w=win(receivable?'Alta de Cuentas por Cobrar':'Alta de Cuentas por Pagar',true);w.insertAdjacentHTML('beforeend',`<div class="module-heading"><strong>CARLOS ESPINDOLA</strong><strong>${receivable?'Movimiento de Cliente':'Movimiento de Proveedor'}</strong></div><form class="form-area"><div class="form-grid"><label>Clave ${receivable?'Cliente':'Proveedor'}</label><input name="party_code"><label>Tipo de Cuenta</label><input name="account_type" type="number"><label>Fecha</label><input name="entry_date" type="date" value="${new Date().toISOString().slice(0,10)}"><label>Documento</label><input name="reference"><label>Importe</label><input name="amount" type="number" min="0.01" step="0.01"></div></form><div class="button-row"><button class="win-button save">💾 Guardar</button><button class="win-button close-account">🚪 Salir</button></div><div class="status-mini">${today()} &nbsp;&nbsp; Movimiento de cuenta</div>`);w.querySelector('.close-account').onclick=()=>w.remove();w.querySelector('.save').onclick=async()=>{const data={...Object.fromEntries(new FormData(w.querySelector('form'))),ledger};const r=await fetch('/api/account-entry',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),out=await r.json();if(r.ok){toast('Movimiento de cuenta guardado');w.remove()}else toast(out.error)}}
function openCancellation(category){
  const names={PURCHASE:'Cancelación de Compra',SALE:'Cancelación de Productos de una Venta',CUSTOMER_RETURN:'Cancelación de Devolución de Cliente',SUPPLIER_RETURN:'Cancelación de Devolución a Proveedor'};
  if(category!=='SALE'){
    const w=win(names[category],true);
    w.insertAdjacentHTML('beforeend',`<div class="module-heading"><strong>${company()}</strong><strong>${names[category]}</strong></div><form class="form-area"><div class="form-grid"><label>Folio original</label><input name="folio" autofocus><label>Motivo</label><input name="reason" class="span3"></div><p>La cancelación conserva el documento original, revierte sus existencias y ajusta el saldo correspondiente.</p></form><div class="button-row"><button class="win-button cancel-save">Cancelar documento</button><button class="win-button cancel-close">Salir</button></div>`);
    w.querySelector('.cancel-close').onclick=()=>w.remove();
    w.querySelector('.cancel-save').onclick=async()=>{const data={...Object.fromEntries(new FormData(w.querySelector('form'))),category};const r=await fetch('/api/cancellations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),out=await r.json();if(r.ok){toast(`Documento cancelado; ${out.lines} partidas revertidas`);w.remove()}else toast(out.error)};
    return;
  }
  const w=win(names[category]);
  w.insertAdjacentHTML('beforeend',`<div class="module-heading"><strong>${company()}</strong><strong>Cancelar productos de una venta</strong><span>Busca el folio y selecciona sólo los productos que deseas cancelar</span></div><div class="searchbar"><label>Folio de venta <input name="folio" autofocus></label><button class="win-button find-sale">Buscar venta</button></div><div class="sale-cancellation-summary"></div><div class="table-wrap"><table class="data-table cancellation-items"><thead><tr><th>Cancelar</th><th>Producto</th><th>Revista</th><th>Edición</th><th>Vendidos</th><th>Cancelados</th><th>Disponibles</th><th>Cantidad</th><th>Importe actual</th></tr></thead><tbody><tr><td colspan="9">Escribe el folio de la venta</td></tr></tbody></table></div><div class="form-area"><label>Motivo de la cancelación</label><textarea name="reason" placeholder="Explica por qué se cancela el producto"></textarea></div><div class="button-row"><button class="win-button cancel-selected" disabled>Cancelar productos seleccionados</button><button class="win-button cancel-close">Salir</button></div><div class="status-mini">La venta y sus cancelaciones permanecerán en el historial</div>`);
  const body=w.querySelector('tbody'),folioInput=w.querySelector('[name=folio]'),cancelButton=w.querySelector('.cancel-selected');
  const load=async()=>{
    const folio=folioInput.value.trim();if(!folio){toast('Escribe el folio de la venta');return}
    const response=await fetch(`/api/sales/${encodeURIComponent(folio)}/items`),data=await response.json();
    if(!response.ok){body.innerHTML=`<tr><td colspan="9">${safe(data.error)}</td></tr>`;cancelButton.disabled=true;return}
    w.querySelector('.sale-cancellation-summary').innerHTML=`<b>${safe(data.document.folio)}</b> · ${safe(data.document.party_name)} · ${safe(data.document.document_date)} · Total actual: ${money(data.document.total)}`;
    body.innerHTML=data.items.map(item=>`<tr data-item-id="${item.id}"><td><input class="select-cancel" type="checkbox" ${item.available_quantity<=0?'disabled':''}></td><td>${safe(item.publication_code)}</td><td>${safe(item.title)}</td><td>${safe(item.edition_number)}</td><td>${item.quantity}</td><td>${item.cancelled_quantity}</td><td>${item.available_quantity}</td><td><input class="cancel-quantity" type="number" min="1" max="${item.available_quantity}" value="${item.available_quantity>0?item.available_quantity:0}" ${item.available_quantity<=0?'disabled':''}></td><td>${money(item.available_amount)}</td></tr>`).join('');
    cancelButton.disabled=!data.items.some(item=>item.available_quantity>0);
  };
  w.querySelector('.find-sale').onclick=load;folioInput.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();load()}};w.querySelector('.cancel-close').onclick=()=>w.remove();
  cancelButton.onclick=async()=>{
    const items=[...body.querySelectorAll('tr')].filter(row=>row.querySelector('.select-cancel')?.checked).map(row=>({item_id:Number(row.dataset.itemId),quantity:Number(row.querySelector('.cancel-quantity').value)}));const reason=w.querySelector('[name=reason]').value.trim();
    if(!items.length){toast('Selecciona por lo menos un producto');return}if(!reason){toast('Escribe el motivo de la cancelación');return}if(!confirm('¿Cancelar únicamente los productos y cantidades seleccionados?'))return;
    const response=await fetch(`/api/sales/${encodeURIComponent(folioInput.value.trim())}/cancel-items`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason,items})}),data=await response.json();
    if(!response.ok){toast(data.error);return}toast(`${data.canceled_copies} ejemplares cancelados. Total actual ${money(data.document_total)}`);w.querySelector('[name=reason]').value='';load();loadDashboard();
  };
}
function openOperation(kind){
  const title=kind.includes('COMPRA')?'Modulo de Compras':kind.includes('PROVEEDOR')?'Devolucion a Proveedores(Almacen Devoluciones)':kind==='VENTA'?'Modulo de Ventas':kind;const w=win(title);
  const folio=String(Date.now()).slice(-6);const isSale=kind==='VENTA';const isTransfer=kind==='TRASPASO';const isSupplier=kind.includes('COMPRA')||kind.includes('PROVEEDOR')||kind.includes('BODEGA');
  w.insertAdjacentHTML('beforeend',`<div class="operation-head"><label>Folio Interno</label><input name="folio" value="${folio}" readonly><label>Fecha</label><input name="operation_date" value="${today()}"><label>Clave ${isSupplier?'Proveedor':'Cliente'}</label><input name="party_code"><label>Nombre</label><input name="party_name">${isSale?'<label>Tipo de Venta</label><select name="sale_type"><option>CONTADO</option><option>CREDITO</option></select>':''}${isTransfer?'<label>Origen</label><select name="source_store"><option>BODEGA</option><option>DEVOLUCIONES</option></select><label>Destino</label><select name="destination_store"><option>DEVOLUCIONES</option><option>BODEGA</option></select>':kind.includes('PROVEEDOR')||kind.includes('BODEGA')?'<label>Almacén</label><select name="source_store"><option>BODEGA</option><option>DEVOLUCIONES</option></select>':''}</div><div class="ledger"><table class="data-table entry-table"><thead><tr><th>Clave revista</th><th>Nombre Revista</th><th>No.Edición</th><th>Precio</th><th>Cantidad</th><th>Descuento</th><th>Importe</th><th></th></tr></thead><tbody></tbody></table><button class="win-button add-line">＋ Partida</button></div><div class="totals"><div><span class="parts">Total de Partidas: 0</span><br><br><span class="copies">Total de Revistas: 0</span></div><div class="total-box"><label>Subtotal</label><input name="subtotal" value="$ 0.00" readonly><label>Descuento</label><input name="discount_total" value="$ 0.00" readonly><label>I.V.A.</label><input name="tax_total" value="$ 0.00" readonly><label>Total</label><input name="total" value="$ 0.00" readonly></div></div><div class="button-row"><button class="win-button save">💾 Guardar(F2)</button><button class="win-button close-op">🚪 Salir</button><button class="win-button another">📖 Dar de Alta Otra</button></div><div class="status-mini">${today()} &nbsp;&nbsp;&nbsp;&nbsp; Folio de la operación</div>`);
  const tbody=w.querySelector('tbody');
  const addLine=()=>{const tr=document.createElement('tr');tr.innerHTML='<td><input class="pub" size="10"></td><td class="title"></td><td><input class="edition" size="8"></td><td><input class="price" type="number" step="0.01" min="0"></td><td><input class="quantity" type="number" value="1" min="1"></td><td><input class="discount" type="number" value="0" min="0" max="100"></td><td class="amount">$0.00</td><td><button class="remove-line">×</button></td>';tbody.appendChild(tr);const lookup=async()=>{const pub=tr.querySelector('.pub').value,ed=tr.querySelector('.edition').value;if(!pub||!ed)return;const r=await fetch(`/api/edition-lookup?publication=${encodeURIComponent(pub)}&edition=${encodeURIComponent(ed)}`);const out=await r.json();if(!r.ok){toast(out.error);return}tr.dataset.editionId=out.id;tr.dataset.tax=out.tax;tr.querySelector('.title').textContent=out.title;tr.querySelector('.price').value=out.price;recalculate()};tr.querySelector('.pub').onchange=lookup;tr.querySelector('.edition').onchange=lookup;tr.querySelectorAll('input').forEach(i=>i.oninput=recalculate);tr.querySelector('.remove-line').onclick=()=>{tr.remove();recalculate()}};
  const recalculate=()=>{let subtotal=0,discountTotal=0,taxTotal=0,copies=0;tbody.querySelectorAll('tr').forEach(tr=>{const price=Number(tr.querySelector('.price').value||0),quantity=Number(tr.querySelector('.quantity').value||0),discount=Number(tr.querySelector('.discount').value||0),tax=Number(tr.dataset.tax||0),base=price*quantity,discounted=base*(1-discount/100),taxAmount=discounted*tax/100;subtotal+=base;discountTotal+=base-discounted;taxTotal+=taxAmount;copies+=quantity;tr.querySelector('.amount').textContent=money(discounted+taxAmount)});w.querySelector('.parts').textContent=`Total de Partidas: ${tbody.children.length}`;w.querySelector('.copies').textContent=`Total de Revistas: ${copies}`;w.querySelector('[name=subtotal]').value=money(subtotal);w.querySelector('[name=discount_total]').value=money(discountTotal);w.querySelector('[name=tax_total]').value=money(taxTotal);w.querySelector('[name=total]').value=money(subtotal-discountTotal+taxTotal)};
  w.querySelector('.add-line').onclick=addLine;w.querySelector('.close-op').onclick=()=>w.remove();w.querySelector('.another').onclick=()=>openOperation(kind);addLine();
  w.querySelector('.save').onclick=async()=>{const q=n=>w.querySelector(`[name=${n}]`)?.value||'';const items=[...tbody.querySelectorAll('tr')].map(tr=>({edition_id:tr.dataset.editionId,price:tr.querySelector('.price').value,quantity:tr.querySelector('.quantity').value,discount:tr.querySelector('.discount').value}));const data={kind,folio:q('folio'),operation_date:isoDate(q('operation_date')),party_code:q('party_code'),party_name:q('party_name'),sale_type:q('sale_type'),source_store:q('source_store'),destination_store:q('destination_store'),items};const r=await fetch('/api/documents',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const out=await r.json();if(r.ok){if(kind==='COMPRA'&&confirm('Compra guardada. ¿Desea generar los pedidos utilizando los paquetes de clientes?')){const generated=await fetch(`/api/documents/${out.id}/generate-orders`,{method:'POST'}),result=await generated.json();toast(generated.ok?`Se generaron ${result.orders} pedidos con ${result.copies} revistas`:result.error)}else toast(`Movimiento ${out.id} guardado. Total ${money(out.total)}`);w.remove()}else toast(out.error||'No fue posible guardar el movimiento')};
}
function reportSlug(title){const t=title.toLowerCase();if(t.includes('inventario')||t.includes('existencia'))return'inventory';if(t.includes('traspaso'))return'transfers';if(t.includes('pedido'))return'orders';if(t.includes('paquete')||t.includes('distribucion')||t.includes('ruta')||t.includes('locales cerrados'))return'distribution';if(t.includes('cuenta por pagar')||t.includes('liquidacion')||t.includes('estado de cuenta')&&t.includes('proveedor'))return'payables';if(t.includes('cuenta por cobrar')||t.includes('estado de cuenta'))return'receivables';if(t.includes('devoluciones a proveedor')||t.includes('predevolucion'))return'supplier-returns';if(t.includes('devolucion')||t.includes('devoluciones'))return'customer-returns';if(t.includes('compra'))return'purchases';if(t.includes('flujo')||t.includes('corte')||t.includes('vale')||t.includes('movimientos de clientes'))return'cash';return'sales'}
function openReport(title){
  const w=win(title);const slug=reportSlug(title);let lastData={columns:[],rows:[]};w.insertAdjacentHTML('beforeend',`<div class="module-heading"><strong>CARLOS ESPINDOLA</strong><strong>${title}</strong></div><div class="searchbar report-filter"><label>Fecha Inicial <input name="start" type="date" value="2010-01-01"></label><label>Fecha Final <input name="end" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Buscar <input name="code" placeholder="Cualquier dato"></label><button class="win-button find-report">🔎 Consultar</button></div><div class="table-wrap"><table class="data-table report-table"><thead></thead><tbody></tbody></table></div><div class="totals report-totals"><span class="count">Registros: 0</span><span class="summary"></span></div><div class="button-row"><button class="win-button print-report">🖨 Imprimir reporte</button><button class="win-button close-report">🚪 Salir</button></div><div class="status-mini">${today()} &nbsp;&nbsp; ${title}</div>`);
  const load=async()=>{const start=w.querySelector('[name=start]').value,end=w.querySelector('[name=end]').value,code=w.querySelector('[name=code]').value;const response=await fetch(`/api/reports/${slug}?start=${start}&end=${end}&code=${encodeURIComponent(code)}`);const data=await response.json();if(!response.ok){toast(data.error);return}lastData=data;w.querySelector('thead').innerHTML=`<tr>${data.columns.map(c=>`<th>${c}</th>`).join('')}</tr>`;w.querySelector('tbody').innerHTML=data.rows.map(row=>`<tr>${data.columns.map(c=>`<td>${format(row[c],c)}</td>`).join('')}</tr>`).join('');w.querySelector('.count').textContent=`Registros: ${data.count}`;w.querySelector('.summary').textContent=Object.entries(data.totals).map(([k,v])=>`${k}: ${money(v)}`).join('    ')};
  w.querySelector('.find-report').onclick=load;w.querySelector('[name=code]').onkeydown=e=>e.key==='Enter'&&load();w.querySelector('.print-report').onclick=()=>printTable(title,lastData.columns,lastData.rows);w.querySelector('.close-report').onclick=()=>w.remove();load();
}
function openAbout(){const w=win('Acerca del sistema',true);w.insertAdjacentHTML('beforeend',`<div class="form-area" style="text-align:center;padding-top:70px"><h2>Gestión de Publicaciones</h2><p>Compras, distribución, inventario, ventas y cobranza</p><p>${company()}</p><p>Aplicación web local para Windows</p></div><div class="button-row"><button class="win-button close-about">Aceptar</button></div>`);w.querySelector('.close-about').onclick=()=>w.remove()}
function openBackup(mode='backup'){const w=win('Respaldo y migración',true);w.insertAdjacentHTML('beforeend',`<div class="form-area backup-area"><h2>Protege y traslada tu información</h2><p>Elige una opción. Los archivos descargados pueden guardarse en una memoria, disco externo o servicio de almacenamiento.</p><div class="backup-options"><button class="backup-full"><b>💾 Crear respaldo completo</b><span>Descarga una carpeta comprimida con un archivo de Excel separado por cada módulo.</span></button><button class="backup-format"><b>📄 Descargar formato para migrar</b><span>Obtén un Excel vacío con instrucciones y columnas sencillas para preparar información de otro sistema.</span></button><label class="backup-import"><b>📤 Importar información</b><span>Selecciona el formato lleno para agregar o actualizar clientes, proveedores, publicaciones, ediciones y paquetes.</span><input type="file" accept=".xlsx" name="archivo"><em>Ningún archivo seleccionado</em></label></div><div class="import-result"></div></div><div class="button-row"><button class="win-button backup-close">Cerrar</button></div>`);const download=url=>{const a=document.createElement('a');a.href=url;document.body.appendChild(a);a.click();a.remove()};w.querySelector('.backup-full').onclick=()=>{toast('Preparando el respaldo. La descarga comenzará al terminar.');download('/api/respaldo/completo')};w.querySelector('.backup-format').onclick=()=>download('/api/respaldo/formato');const input=w.querySelector('[name=archivo]');input.onchange=async()=>{if(!input.files.length)return;w.querySelector('.backup-import em').textContent=input.files[0].name;const form=new FormData();form.append('archivo',input.files[0]);w.querySelector('.import-result').textContent='Integrando la información…';const response=await fetch('/api/respaldo/importar',{method:'POST',body:form}),data=await response.json();if(response.ok){w.querySelector('.import-result').innerHTML=`<strong>${data.mensaje}</strong><br>${Object.entries(data.registros).map(([name,count])=>`${name}: ${count}`).join(' · ')}`;loadDashboard()}else w.querySelector('.import-result').textContent=data.error||'No se pudo integrar la información'};w.querySelector('.backup-close').onclick=()=>w.remove();if(mode==='migration-download')w.querySelector('.backup-format').click();if(mode==='migration-import')input.click()}
function company(){return document.querySelector('#company-name')?.textContent||'Mi Distribuidora'}
async function loadDashboard(){const data=await fetch('/api/dashboard').then(r=>r.json());document.querySelectorAll('[data-metric]').forEach(el=>{const value=data[el.dataset.metric]??0;el.textContent=Number(value).toLocaleString('es-MX')})}
function openSettings(){
  const w=win('Configuración de la empresa',true),hasImage=Boolean(document.querySelector('.brand-mark img'));
  w.insertAdjacentHTML('beforeend',`<form class="form-area"><div class="company-image-panel"><div class="company-image-preview">${hasImage?'<img src="/api/company-image" alt="Imagen actual">':'Sin imagen'}</div><div class="company-image-actions"><label>Fotografía o logotipo de la empresa</label><input name="company_image" type="file" accept="image/png,image/jpeg,image/webp"><small>Formatos permitidos: PNG, JPG o WEBP. Tamaño máximo: 5 MB.</small></div></div><div class="form-grid"><label>Nombre de la empresa</label><input name="company_name" value="${company()}"><label>Nombre del sistema</label><input name="system_name" value="Gestión de Publicaciones"><label>Moneda</label><select name="currency"><option>MXN</option><option>USD</option><option>EUR</option></select><label>Color principal</label><input name="accent_color" type="color" value="${getComputedStyle(document.body).getPropertyValue('--accent').trim()||'#2563eb'}"></div></form><div class="button-row"><button class="win-button settings-save">Guardar configuración</button><button class="win-button settings-close">Cerrar</button></div>`);
  const fileInput=w.querySelector('[name=company_image]');
  fileInput.onchange=()=>{if(!fileInput.files.length)return;const preview=w.querySelector('.company-image-preview'),reader=new FileReader();reader.onload=()=>preview.innerHTML=`<img src="${reader.result}" alt="Vista previa">`;reader.readAsDataURL(fileInput.files[0])};
  w.querySelector('.settings-close').onclick=()=>w.remove();
  w.querySelector('.settings-save').onclick=async()=>{const form=w.querySelector('form'),data=Object.fromEntries(new FormData(form));delete data.company_image;const settingsResponse=await fetch('/api/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!settingsResponse.ok){toast('No se pudo guardar la configuración');return}if(fileInput.files.length){const imageData=new FormData();imageData.append('image',fileInput.files[0]);const imageResponse=await fetch('/api/company-image',{method:'POST',body:imageData}),out=await imageResponse.json();if(!imageResponse.ok){toast(out.error||'No se pudo guardar la imagen');return}}location.reload()};
}
function toast(msg){const t=document.createElement('div');t.className='toast';t.textContent=msg;document.querySelector('#desktop').appendChild(t);setTimeout(()=>t.remove(),2600)}
function format(v,key){if(v==null)return '';const k=String(key).toLowerCase();if(k==='active')return Number(v)===1?'Activo':'Inactivo';if(['balance','price','precio','total','exento','gravado','iva','cargo','abono','saldo','importe','cobrado','efectivo','cambio','retiro'].includes(k))return Number(v).toLocaleString('es-MX',{style:'currency',currency:'MXN'});return String(v).replaceAll('&','&amp;').replaceAll('<','&lt;')}
function money(v){return Number(v||0).toLocaleString('es-MX',{style:'currency',currency:'MXN'})}
function today(){return document.body.dataset.today}function isoDate(d){const [a,m,y]=d.split('/');return `${y}-${m}-${a}`}
buildMenus();buildToolbar();loadDashboard();
document.querySelectorAll('[data-quick]').forEach(button=>button.onclick=()=>({purchase:()=>openOperation('COMPRA'),sale:()=>openOperation('VENTA'),customers:()=>openCatalog('customers','Clientes'),inventory:()=>openReport('Reporte de Inventario'),returns:()=>openOperation('DEVOLUCION DE CLIENTE'),cash:()=>openReport('Flujo de Efectivo'),backup:()=>openBackup()}[button.dataset.quick]||(()=>{}))());
new MutationObserver(()=>document.querySelectorAll('.module-heading strong').forEach(node=>{if(node.textContent==='CARLOS ESPINDOLA')node.textContent=company()})).observe(document.querySelector('#windows'),{childList:true,subtree:true});
